class Solution {
public:
    int countPairs(vector<int>& nums) {
        unordered_map<int, int> freq;
        int ans = 0;
        for (int x : nums) {
            string s = to_string(x);
            while (s.size() < 7) s = "0" + s;
            unordered_set<int> forms;
            forms.insert(stoi(s));
            int L = s.size();
            for (int i = 0; i < L; ++i) {
                for (int j = i + 1; j < L; ++j) {
                    swap(s[i], s[j]);
                    forms.insert(stoi(s));
                    for (int k = i + 1; k < L; ++k) {
                        for (int l = k + 1; l < L; ++l) {
                            swap(s[k], s[l]);
                            forms.insert(stoi(s));
                            swap(s[k], s[l]);
                        }
                    }
                    swap(s[i], s[j]);
                }
            }
            for (int f : forms) {
                if (freq.count(f)) ans += freq[f];
            }
            freq[x]++;
        }
        return ans;
    }
};

class Solution {
    public int countPairs(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        int ans = 0;
        for (int x : nums) {
            String sStr = Integer.toString(x);
            while (sStr.length() < 7) sStr = "0" + sStr;
            char[] s = sStr.toCharArray();
            Set<Integer> forms = new HashSet<>();
            forms.add(Integer.parseInt(new String(s)));
            int L = s.length;
            for (int i = 0; i < L; ++i) {
                for (int j = i + 1; j < L; ++j) {
                    char temp = s[i]; s[i] = s[j]; s[j] = temp;
                    forms.add(Integer.parseInt(new String(s)));
                    for (int k = i + 1; k < L; ++k) {
                        for (int l = k + 1; l < L; ++l) {
                            char temp2 = s[k]; s[k] = s[l]; s[l] = temp2;
                            forms.add(Integer.parseInt(new String(s)));
                            s[l] = s[k]; s[k] = temp2;
                        }
                    }
                    s[j] = s[i]; s[i] = temp;
                }
            }
            for (int f : forms) {
                ans += freq.getOrDefault(f, 0);
            }
            freq.put(x, freq.getOrDefault(x, 0) + 1);
        }
        return ans;
    }
}

var countPairs = function(nums) {
    const freq = new Map();
    let ans = 0;
    for (const x of nums) {
        const s = String(x).padStart(7, '0').split('');
        const forms = new Set();
        forms.add(parseInt(s.join(''), 10));
        const L = s.length;
        for (let i = 0; i < L; i++) {
            for (let j = i + 1; j < L; j++) {
                let temp = s[i]; s[i] = s[j]; s[j] = temp;
                forms.add(parseInt(s.join(''), 10));
                for (let k = i + 1; k < L; k++) {
                    for (let l = k + 1; l < L; l++) {
                        let temp2 = s[k]; s[k] = s[l]; s[l] = temp2;
                        forms.add(parseInt(s.join(''), 10));
                        s[k] = s[l]; s[l] = temp2;
                    }
                }
                s[i] = s[j]; s[j] = temp;
            }
        }
        for (const f of forms) {
            if (freq.has(f)) ans += freq.get(f);
        }
        freq.set(x, (freq.get(x) || 0) + 1);
